#!/usr/bin/env python3
"""Compute the reference numeric ledger for CSX-037_Q1."""

from __future__ import annotations

import html
import json
import math
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-037_Q1"
EVENT_ID = "CSX-037"
OUTPUT_NAME = "computed_gt.json"

TASK_DIR = Path(__file__).resolve().parent
WORKSPACE_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_DIR = WORKSPACE_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

REPORT_REL = "data/event_reports/event_reports_001_Locked_package_evidence_report.bin"
ANCHOR_REL = "data/event_reports/event_reports_003_Locked_event_anchor_January_2016_East_Asia_cold_wave_in_Hong_Kong.json"
OPEN_METEO_REL = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json"


def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8"))


def clean_html_report(rel_path: str) -> str:
    raw = (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="replace")
    raw = re.sub(r"<(script|style).*?</\1>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    raw = re.sub(r"<[^>]+>", " ", raw)
    return html.unescape(re.sub(r"\s+", " ", raw)).strip()


def min_value(values: list[float]) -> float:
    return min(float(value) for value in values)


def max_value(values: list[float]) -> float:
    return max(float(value) for value in values)


def longest_true_run(mask: list[bool]) -> int:
    best = 0
    current = 0
    for is_true in mask:
        if is_true:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def wind_chill_c(temperature_c: float, wind_speed_kmh: float) -> float:
    return (
        13.12
        + 0.6215 * temperature_c
        - 11.37 * (wind_speed_kmh**0.16)
        + 0.3965 * temperature_c * (wind_speed_kmh**0.16)
    )


def report_flags() -> dict[str, Any]:
    text = clean_html_report(REPORT_REL)
    lowered = text.lower()
    low_match = re.search(r"was ([0-9.]+) degrees, which is the ninth lowest", text)
    return {
        "hko_low_c": float(low_match.group(1)) if low_match else None,
        "intense_cold_surge": "intense cold surge" in lowered,
        "freezing_rain_icing": "freezing rain and icing occurred" in lowered,
        "ice_pellets": "ice pellets" in lowered,
        "wind_chill_mentioned": "wind chill" in lowered,
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON shape",
                "points": 4,
                "description": "Returns the five requested top-level fields with nested temperature, wind, and snow ledgers.",
                "partial_credit": "Give 2 points if all metric groups are present but naming or nesting differs.",
            },
            {
                "name": "Temperature duration and load",
                "points": 5,
                "description": "Computes minimum temperature, hours at or below 7 C, longest cold run, and cold-load degree-hours with stated rounding.",
                "partial_credit": "Give up to 3 points for correct threshold counting but an incorrect or missing cold-load formula.",
            },
            {
                "name": "Wind coupling",
                "points": 4,
                "description": "Computes peak gust, cold-plus-gust overlap hours, and minimum wind chill from temperature and 10 m wind speed.",
                "partial_credit": "Give up to 2 points if the overlap count is correct but wind chill is rounded or formula-applied incorrectly.",
            },
            {
                "name": "Snow-depth gate",
                "points": 3,
                "description": "Uses total snowfall and maximum snow depth to fail the snow-accumulation gate.",
                "partial_credit": "Give 1 point for using snowfall alone without the depth gate.",
            },
            {
                "name": "Final label",
                "points": 2,
                "description": "Labels the episode as sustained cold surge with wind chill rather than snow accumulation.",
                "partial_credit": "Give 1 point if the label names cold surge but omits wind chill or the snow contrast.",
            },
            {
                "name": "Rounding and units",
                "points": 2,
                "description": "Reports units or unit-implied field names and applies the requested decimal precision.",
                "partial_credit": "Give 1 point for correct values with inconsistent precision.",
            },
        ],
    }


def compute() -> dict[str, Any]:
    anchor = read_json(ANCHOR_REL)
    meteo = read_json(OPEN_METEO_REL)
    hourly = meteo["hourly"]

    times = hourly["time"]
    temperatures = [float(value) for value in hourly["temperature_2m"]]
    wind_speeds = [float(value) for value in hourly["wind_speed_10m"]]
    gusts = [float(value) for value in hourly["wind_gusts_10m"]]
    snowfall = [float(value) for value in hourly["snowfall"]]
    snow_depth = [float(value) for value in hourly["snow_depth"]]

    cold_mask = [value <= 7.0 for value in temperatures]
    cold_load = sum(max(0.0, 7.0 - value) for value in temperatures)
    wind_chill_values = [
        wind_chill_c(temperature, wind_speed)
        for temperature, wind_speed in zip(temperatures, wind_speeds)
    ]

    primary_gt = {
        "event_window": f"{times[0]}/{times[-1]}",
        "temperature": {
            "min_c": round(min_value(temperatures), 1),
            "hours_le_7c": sum(cold_mask),
            "longest_run_h": longest_true_run(cold_mask),
            "cold_load_c_h": round(cold_load, 1),
        },
        "wind": {
            "peak_gust_kmh": round(max_value(gusts), 1),
            "overlap_h": sum(temp <= 7.0 and gust >= 55.0 for temp, gust in zip(temperatures, gusts)),
            "min_wind_chill_c": round(min(wind_chill_values), 2),
        },
        "snow": {
            "total_cm": round(sum(snowfall), 2),
            "max_depth_m": round(max_value(snow_depth), 2),
            "passes_depth_gate": max_value(snow_depth) > 0.0 and sum(snowfall) >= 1.0,
        },
        "final_label": "sustained_cold_surge_with_wind_chill_not_snow_accumulation",
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "tolerances": {
            "temperature_c": 0.1,
            "cold_load_c_h": 0.1,
            "wind_kmh": 0.1,
            "wind_chill_c": 0.05,
            "snowfall_cm": 0.01,
            "snow_depth_m": 0.01,
            "hour_counts": 0,
        },
        "formulas": {
            "cold_load_c_h": "sum(max(0, 7 - temperature_c)) over 48 hourly values",
            "cold_hours": "count(temperature_c <= 7)",
            "longest_run": "longest consecutive hourly run with temperature_c <= 7",
            "gust_overlap": "count(temperature_c <= 7 and gust_kmh >= 55)",
            "wind_chill_c": "13.12 + 0.6215*T - 11.37*V^0.16 + 0.3965*T*V^0.16",
            "snow_depth_gate": "max_depth_m > 0 and total_snowfall_cm >= 1",
        },
        "supporting_values": {
            "event_dates": anchor["temporal_window"],
            "report_flags": report_flags(),
            "hourly_record_count": len(times),
            "thresholds": {"cold_c": 7.0, "gust_kmh": 55.0, "snowfall_cm": 1.0, "snow_depth_m": 0.0},
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [REPORT_REL, ANCHOR_REL, OPEN_METEO_REL],
            "notes": "All numeric values are rebuilt from local CSX-037 package files.",
        },
    }


def main() -> None:
    result = compute()
    output = TASK_DIR / OUTPUT_NAME
    output.write_text(json.dumps(result, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
